            using var timer=new System.Windows.Forms.Timer{Interval=60};var filtered=false;timer.Tick+=(_,_)=>{var list=Application.OpenForms.OfType<OrderListForm>().FirstOrDefault();if(list is null||list.Grid.Rows.Count==0)return;filtered=list.StateBox.SelectedIndex==1&&api.Paths.Any(p=>p.Contains("status=CHO_XAC_NHAN"));timer.Stop();UnsavedChanges.DiscardAndClose(list);};timer.Start();view.MetricButtons["waiting"].PerformClick();Assert(filtered,"Waiting drilldown not filtered");
            using var stockTimer=new System.Windows.Forms.Timer{Interval=60};var low=false;stockTimer.Tick+=(_,_)=>{var stock=Application.OpenForms.OfType<StockListForm>().FirstOrDefault();if(stock is null||stock.Grid.Rows.Count==0)return;low=stock.BelowBox.Checked&&stock.ThresholdBox.Value==3;stockTimer.Stop();UnsavedChanges.DiscardAndClose(stock);};view.ThresholdBox.Value=3;Assert(!view.MetricButtons["stock"].Enabled,"Changed threshold retained stale metric");await view.LoadAsync();stockTimer.Start();view.MetricButtons["stock"].PerformClick();Assert(low,"Stock drilldown threshold missing");api.FailSecondPage=true;await view.LoadAsync();Assert(view.MetricLabels["returns"].Text.Contains("chưa sẵn sàng")&&!view.MetricLabels["returns"].Text.StartsWith("94")&&view.MetricLabels["waiting"].Text.StartsWith("20"),"Dashboard partial/error leaked or other task blocked");await Capture(owner,"UI02-dashboard-partial-failure");UnsavedChanges.DiscardAndClose(owner);
